(()=>{'use strict';
const {MODULES,LESSONS,PATHS,FUNCTIONS,CASES,PROMPTS,SOURCES}=FINANCE,$=s=>document.querySelector(s),main=$('#main');
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(x,d=0)=>Number.isFinite(x)?x.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d}):'—',pct=(x,d=2)=>Number.isFinite(x)?fmt(x*100,d)+'%':'—';
let storageOK=true,state={done:[],saved:[],notes:{},answers:{},last:null};
try{const raw=JSON.parse(localStorage.getItem('finance-lab-v1')||'null');if(raw&&typeof raw==='object'){state.done=Array.isArray(raw.done)?raw.done.filter(x=>LESSONS.some(l=>l.id===x)):[];state.saved=Array.isArray(raw.saved)?raw.saved.filter(x=>LESSONS.some(l=>l.id===x)):[];state.notes=raw.notes&&typeof raw.notes==='object'?raw.notes:{};state.answers=raw.answers&&typeof raw.answers==='object'?raw.answers:{};state.last=LESSONS.some(l=>l.id===raw.last)?raw.last:null;}}catch{storageOK=false;}
function save(){try{localStorage.setItem('finance-lab-v1',JSON.stringify(state));}catch{storageOK=false;toast('瀏覽器無法保存紀錄；本次操作仍可使用。');}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function icon(name){const shapes={compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>',calculator:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h1m3 0h1m3 0h.1M8 15h1m3 0h1m3 0h.1M8 18h1m3 0h1m3 0h.1"/>',chart:'<path d="M4 4v16h17M7 15l4-5 4 3 5-7"/>',layers:'<path d="m3 7 9-4 9 4-9 4Zm0 5 9 4 9-4M3 17l9 4 9-4"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 7h14M5 17h14"/>',candles:'<path d="M6 3v4m0 9v5m6-16v6m0 5v4m6-17v3m0 8v6"/><rect x="4" y="7" width="4" height="9" rx=".5"/><rect x="10" y="11" width="4" height="5" rx=".5"/><rect x="16" y="6" width="4" height="8" rx=".5"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',check:'<path d="m5 12 4 4L19 6"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${shapes[name]||shapes.chart}</svg>`;}
const arrow='<span aria-hidden="true">↗</span>';
const moduleOf=id=>MODULES.find(m=>m.id===id),lessonOf=id=>LESSONS.find(l=>l.id===id),done=id=>state.done.includes(id);
function head(title,desc,en,crumb=[]){return `<div class="page-head"><div class="breadcrumbs"><a href="#/">首頁</a>${crumb.map(([s,h])=>`<span>／</span>${h?`<a href="${h}">${E(s)}</a>`:`<span>${E(s)}</span>`}`).join('')}</div>${en?`<div class="eyebrow">${E(en)}</div>`:''}<h1>${E(title)}</h1><p class="head-description">${E(desc)}</p></div>`;}
function sectionHead(en,title,desc,link,label='探索更多'){return `<div class="section-head"><div><div class="eyebrow">${en}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${link?`<a class="text-link" href="${link}">${label} ↗</a>`:''}</div>`;}
function pathCard(p){const count=p.ids.filter(done).length;return `<a href="#/path/${p.id}" class="path-card"><div class="card-top"><span class="round-icon">${icon(p.icon)}</span><span class="tag">${p.tag}</span></div><h3>${p.title}</h3><p>${p.desc}</p><div class="card-bottom"><span>${p.ids.length} 個知識點${count?' · 已完成 '+count:''}</span><span class="card-arrow">↗</span></div></a>`;}
function lessonCard(l){return `<a href="#/lesson/${l.id}" class="lesson-card"><span class="overline">${E(l.en)}</span><h3>${E(l.title)}</h3><p>${E(l.summary)}</p><div class="lesson-meta"><span>${l.time} 分鐘閱讀 · 理解練習</span><span class="${done(l.id)?'done':''}">${done(l.id)?'✓ 已完成':'閱讀 →'}</span></div></a>`;}
function caseArt(i=0){const p=i%3===0?'M0 62 25 50 48 58 75 30 100 39 125 20 150 27 180 10 210 18 250 0':i%3===1?'M0 60 30 58 60 52 90 49 120 38 150 33 180 23 210 16 250 2':'M0 40 25 22 50 47 75 15 100 35 125 55 150 25 175 36 200 11 225 23 250 8';return `<div class="case-visual"><span>EXPLORE · ANALYZE · VERIFY</span><svg viewBox="0 0 250 75" preserveAspectRatio="none" aria-hidden="true"><path d="M0 25h250M0 50h250M50 0v75M125 0v75M200 0v75" stroke="#dbeafe" fill="none"/><path d="${p}" transform="translate(0 9)" stroke="#1447e6" stroke-width="2" fill="none"/><path d="M0 70h250" stroke="#cbd5e1"/></svg></div>`;}
function caseCard(c,i){return `<a class="case-card" href="#/case/${c.id}">${caseArt(i)}<div class="case-body"><span class="tag">${c.category}</span><h3>${c.title}</h3><p>${c.desc}</p><div class="card-bottom"><span>${c.status}</span><span class="card-arrow">↗</span></div></div></a>`;}
function home(){const n=LESSONS.length;main.innerHTML=`<div class="container"><section class="hero"><div class="hero-top"><div class="hero-copy"><div class="eyebrow">BUILD YOUR FINANCIAL PERSPECTIVE</div><h1>投資理財的<br><span>探究與實作</span></h1><p class="copyright-credit copyright-credit-top">copyright@北市陽明高中／王聖淵老師</p><p>從理財觀念到數據分析，透過 Excel 與 AI<br class="desktop-break">探究方法、驗證結果，建立自己的財務判斷。</p><div class="hero-actions"><a class="btn btn-primary" href="${state.last?'#/lesson/'+state.last:'#/learn'}">${state.last?'繼續學習':'開始你的學習'} <span>→</span></a><a class="btn btn-ghost" href="#/cases">探索實作案例 ${arrow}</a></div><p class="hero-footnote"><span class="tiny-dot"></span>以理解為起點，以實作累積判斷。</p></div><div class="hero-panel"><div class="panel-top"><div><div class="overline">THE VALUE OF CONSISTENCY</div><h3>讓時間，成為累積的力量。</h3></div><span class="panel-chip">複利探究</span></div><div class="hero-amount">NT$ ${fmt(FM.fv(100000,5000,.04/12,120))}<small>10 年情境試算</small></div>${heroChart()}<div class="chart-legend"><span><i style="background:#1447e6"></i>假設累積值</span><span><i style="background:#d66b00"></i>累積投入</span></div><p class="hero-art-note">本金 10 萬 · 每月期末投入 5,000 · 假設年率 4% 按月計息</p><a href="#/tools/savings" class="panel-note"><span class="round-icon">${icon('chart')}</span><span><strong>每一個假設，都值得驗證。</strong>調整參數，探索不同的可能 ↗</span></a></div></div><div class="metrics"><div class="metric"><strong>7</strong><span><b>主題學習模組</b>從基礎到分析</span></div><div class="metric"><strong>${n}</strong><span><b>具名知識點</b>解說・範例・練習</span></div><div class="metric"><strong>${CASES.length}</strong><span><b>實作案例導讀</b>將觀念連回問題</span></div><div class="metric"><strong>5</strong><span><b>互動探索工具</b>親自計算與驗證</span></div></div></section><section class="section">${sectionHead('YOUR LEARNING JOURNEY','選一條適合你的探索路徑','從你的目標出發，循序建立知識與方法。','#/learn','查看完整課程')}<div class="path-grid">${PATHS.map(pathCard).join('')}</div></section></div><section class="section soft-section"><div class="container">${sectionHead('A CONNECTED BODY OF KNOWLEDGE','把知識連成一張地圖','每個主題都有清楚的定義、方法、案例與延伸方向。','#/glossary','查閱知識名詞')}<div class="module-grid">${MODULES.map(m=>`<a href="#/learn/${m.id}" class="module-card"><span class="round-icon" style="color:${m.color}">${icon(m.icon)}</span><div><h3>${m.title}</h3><p>${m.desc}</p><small>${LESSONS.filter(l=>l.module===m.id).length} 個知識點 · ${m.level} ↗</small></div></a>`).join('')}</div><div class="feature-strip"><div><h3>學會提問，也學會驗證。</h3><p>讓 AI 成為整理思路的夥伴，讓數據與公式成為判斷的依據。</p></div><a class="btn" href="#/prompts">探索 AI 提問模板 ${arrow}</a></div></div></section><section class="section container">${sectionHead('LEARN BY DOING','讓觀念，走進真實問題','從生活規劃到歷史圖表，觀察方法的用途與限制。','#/cases','全部案例')}<div class="case-grid">${[CASES[1],CASES[6],CASES[17]].map(caseCard).join('')}</div></section><div class="container home-copyright"><p class="copyright-credit">copyright@北市陽明高中／王聖淵老師</p></div>`;}
function heroChart(){const arr=Array.from({length:11},(_,i)=>FM.fv(100000,5000,.04/12,i*12)),base=arr.map((_,i)=>100000+60000*i);return `<svg class="hero-chart" viewBox="0 0 450 150" role="img" aria-label="假設年率百分之四的十年累積值與投入比較"><defs><linearGradient id="heroFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#1447e6" stop-opacity=".22"/><stop offset="1" stop-color="#1447e6" stop-opacity="0"/></linearGradient></defs>${[0,1,2].map(i=>`<path d="M0 ${25+i*45}h450" stroke="#cbd5e1"/>`).join('')}<path d="M0 125 ${arr.map((v,i)=>`L${i*45} ${130-v/9000}`).join('')} L450 135Z" fill="url(#heroFill)"/><path d="${base.map((v,i)=>(i?'L':'M')+(i*45)+' '+(130-v/9000)).join(' ')}" stroke="#d66b00" stroke-dasharray="4 5" fill="none"/><path d="${arr.map((v,i)=>(i?'L':'M')+(i*45)+' '+(130-v/9000)).join(' ')}" stroke="#1447e6" stroke-width="2.4" fill="none"/><circle cx="450" cy="${130-arr[10]/9000}" r="4" fill="#1447e6"/>${[0,2,4,6,8,10].map(i=>`<text x="${i*44}" y="148" fill="#64748b" font-size="9">${i} 年</text>`).join('')}</svg>`;}
function learn(filter='all'){let ms=filter==='all'?MODULES:MODULES.filter(m=>m.id===filter);if(!ms.length)return notFound();main.innerHTML=`<div class="container">${head('課程地圖','從問題出發，依照知識之間的關係，建立自己的學習順序。','EXPLORE THE KNOWLEDGE',[['課程地圖']])}<div class="toolbar"><a class="filter ${filter==='all'?'active':''}" href="#/learn">所有主題</a>${MODULES.map(m=>`<a class="filter ${filter===m.id?'active':''}" href="#/learn/${m.id}">${m.title}</a>`).join('')}<span class="filter-count">${LESSONS.length} 個知識點 · ${state.done.length} 個已完成</span></div><div class="page-content">${ms.map(m=>`<section class="module-block"><div class="module-heading"><span class="round-icon" style="color:${m.color}">${icon(m.icon)}</span><div><h2>${m.title}</h2><p>${m.desc}</p></div></div><div class="lesson-grid">${LESSONS.filter(l=>l.module===m.id).map(lessonCard).join('')}</div></section>`).join('')}</div></div>`;}
function pathPage(id){const p=PATHS.find(x=>x.id===id);if(!p)return notFound();const c=p.ids.filter(done).length;main.innerHTML=`<div class="container reading-width">${head(p.title,p.desc,'A PATH THAT FITS YOU',[['課程地圖','#/learn'],[p.tag]])}<div class="page-content"><div class="panel"><div class="table-top"><span class="tag">${p.tag}</span><span class="small muted">已完成 ${c} / ${p.ids.length}</span></div><div class="progress-bar"><i style="width:${c/p.ids.length*100}%"></i></div><p class="small muted">依推薦順序前進，也可以隨時返回不熟悉的知識點。</p><div class="path-steps">${p.ids.map((id,i)=>{const l=lessonOf(id);return `<a href="#/lesson/${id}" class="path-step"><span class="step-marker">${done(id)?'✓':iconSmall(l.module)}</span><div><h3>${l.title}</h3><p>${l.summary}</p></div><span class="card-arrow">↗</span></a>`;}).join('')}</div></div></div></div>`;}
function iconSmall(m){return moduleOf(m).icon==='calculator'?'ƒ':'·';}
function relatedTool(l){return l.module==='planning'?(l.id==='pmt'||l.id==='amortization'?'loan':'savings'):l.module==='evaluation'?(l.id==='volatility'||l.id==='correlation'||l.id==='returns'?'risk':'cashflow'):l.module==='data'||l.module==='indicators'?'chart':null;}
function lessonPage(id){const l=lessonOf(id);if(!l)return notFound();const m=moduleOf(l.module),siblings=LESSONS.filter(x=>x.module===l.module),idx=siblings.indexOf(l),tool=relatedTool(l);state.last=id;save();document.title=l.title+'｜投資理財的探究與實作';main.innerHTML=`<div class="container">${head(m.title,m.desc,m.en,[['課程地圖','#/learn'],[m.title,'#/learn/'+m.id],['知識點']]).replace('<h1>','<h2>').replace('</h1>','</h2>')}<div class="workspace page-content"><aside class="lesson-sidebar" aria-label="相關知識點"><h3>${m.title}</h3>${siblings.map(s=>`<a href="#/lesson/${s.id}" class="${s.id===id?'selected':''}">${done(s.id)?'✓ ':''}${s.title}</a>`).join('')}</aside><article class="article"><div class="eyebrow">${E(l.en)}</div><h1>${E(l.title)}</h1><p class="lead">${E(l.summary)}</p><div class="article-meta"><span>約 ${l.time} 分鐘閱讀</span><span>含理解測驗與實作任務</span><div class="article-actions"><button class="btn btn-small" id="bookmark">${state.saved.includes(id)?'✓ 已收藏':'＋ 收藏知識點'}</button></div></div><h2>理解這個知識點</h2>${l.body.map(p=>`<p>${E(p)}</p>`).join('')}<div class="callout"><b>用一個例子理解</b>${E(l.example)}</div><div class="callout warning"><b>常見誤解與使用限制</b>${E(l.caution)}</div><div class="practice-box"><h3>輪到你，親手驗證。</h3><p>${E(l.practice)}</p>${tool?`<a href="#/tools/${tool}">開啟互動工具 →</a>`:`<a href="#/prompts">使用 AI 提問模板 →</a>`}</div><h2>檢查你的理解</h2><form class="quiz" id="quiz"><span class="tag">理解練習</span><h3>${E(l.question)}</h3>${l.choices.map((c,i)=>`<label><input type="radio" name="answer" value="${i}" ${state.answers[id]===i?'checked':''} required><span>${E(c)}</span></label>`).join('')}<button class="btn btn-primary btn-small" type="submit" style="margin-top:12px">確認答案</button><div class="quiz-result" id="quiz-result" role="status"></div></form><h2>留下你的理解與問題</h2><label class="note-label" for="lesson-note">這個知識點，你會如何用自己的話說明？</label><textarea id="lesson-note" rows="4" placeholder="記錄你的想法、假設或需要繼續查證的問題…">${E(state.notes[id]||'')}</textarea><div class="table-top" style="margin-top:12px"><span class="small muted">紀錄保存在目前瀏覽器，可於「我的學習」匯出。</span><button class="btn btn-small" id="save-note">儲存筆記</button></div>${CASES.some(c=>c.lesson===id)?`<h2>把觀念帶進案例</h2>${CASES.filter(c=>c.lesson===id).map(c=>`<a href="#/case/${c.id}" class="list-row"><div><h3>${c.title}</h3><small>${c.status}</small></div><span>↗</span></a>`).join('')}`:''}<div class="inline-buttons" style="margin-top:30px"><button class="btn btn-primary ${done(id)?'is-complete':''}" id="complete">${done(id)?'✓ 已完成此知識點':'標記為已完成'}</button><a class="btn" href="#/learn/${m.id}">返回主題</a></div><div class="lesson-nav">${idx?`<a href="#/lesson/${siblings[idx-1].id}"><span>← 上一個知識點</span>${siblings[idx-1].title}</a>`:'<span></span>'}${idx<siblings.length-1?`<a href="#/lesson/${siblings[idx+1].id}" style="text-align:right"><span>推薦下一步 →</span>${siblings[idx+1].title}</a>`:`<a href="#/learn"><span>繼續探索 →</span>回到課程地圖</a>`}</div></article></div></div>`;
 $('#bookmark').onclick=()=>{state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();$('#bookmark').textContent=state.saved.includes(id)?'✓ 已收藏':'＋ 收藏知識點';toast(state.saved.includes(id)?'已加入收藏':'已取消收藏');};
 $('#complete').onclick=()=>{state.done=done(id)?state.done.filter(x=>x!==id):[...state.done,id];save();$('#complete').classList.toggle('is-complete',done(id));$('#complete').textContent=done(id)?'✓ 已完成此知識點':'標記為已完成';toast(done(id)?'學習進度已保存':'已取消完成標記');};
 $('#save-note').onclick=()=>{state.notes[id]=$('#lesson-note').value;save();toast('筆記已保存');};
 $('#quiz').onsubmit=e=>{e.preventDefault();const a=Number(new FormData(e.target).get('answer'));state.answers[id]=a;save();$('#quiz-result').textContent=a===l.answer?'✓ 答對了。'+l.choices[l.answer]+'。試著用自己的話說明原因。':'再想一想。正確觀念是「'+l.choices[l.answer]+'」。回到上方說明，檢查你忽略的條件。';$('#quiz-result').style.color=a===l.answer?'#007a55':'#9a3412';};
}
function casesPage(category='全部'){const cats=['全部',...new Set(CASES.map(c=>c.category))];const list=category==='全部'?CASES:CASES.filter(c=>c.category===category);main.innerHTML=`<div class="container">${head('案例實作','從生活理財、專案現金流到歷史股市圖表，練習將方法用在具體問題。','FROM CONCEPT TO CONTEXT',[['案例實作']])}<div class="toolbar case-filters">${cats.map(c=>`<button class="filter ${c===category?'active':''}" data-case-filter="${c}">${c}</button>`).join('')}<span class="filter-count">${list.length} 個案例</span></div><div class="case-grid page-content">${list.map(caseCard).join('')}</div></div>`;document.querySelectorAll('[data-case-filter]').forEach(b=>b.onclick=()=>casesPage(b.dataset.caseFilter));}
function casePage(id){const c=CASES.find(x=>x.id===id);if(!c)return notFound();const l=lessonOf(c.lesson);document.title=c.title+'｜投資理財的探究與實作';main.innerHTML=`<div class="container">${head(c.title,c.desc,'CASE EXPLORATION',[['案例實作','#/cases'],[c.category]])}<div class="case-summary page-content"><article class="article"><span class="tag">${c.status}</span><h2>問題與背景</h2><p>${E(c.context)}</p><h2>探究的方法</h2><div class="step-pills">${c.steps.map(s=>`<span>${s}</span>`).join('')}</div>${c.steps.map((s,i)=>`<h3 style="margin:24px 0 9px">${s}</h3><p>${E(caseStep(c,s,i))}</p>`).join('')}<div class="callout"><b>驗證的重點</b>${E(c.check)}</div><h2>你可以交出的成果</h2><ul><li>一份清楚標明輸入、日期、單位與假設的資料表。</li><li>以所選方法完成分析，保留公式與中間結果。</li><li>寫出至少一個反例、一項限制，以及需要補充的資料。</li></ul>${c.historical?`<div class="callout warning"><b>歷史案例的使用範圍</b>這裡提供教材情境與方法導讀。原始股價附件尚未提供，因此不展示未經驗算的精確買賣點或績效。圖表實驗室另使用固定的合成資料，兩者不混用。</div>`:`<div class="callout warning"><b>練習時保留假設</b>本頁描述教學情境與研究方法。使用工具自訂數字時，請一併記錄條件；結果不代表實際契約或市場承諾。</div>`}<a class="back-link" href="#/cases">← 返回案例實作</a></article><aside class="case-side"><h3>從相關知識開始</h3><p>${l.summary}</p><a class="btn btn-primary" href="#/lesson/${l.id}">${l.title} →</a>${relatedTool(l)?`<a class="btn" href="#/tools/${relatedTool(l)}">開啟練習工具 ↗</a>`:''}<a class="btn" href="#/prompts">準備 AI 提問 ↗</a><div class="disclosure"><h3>分析前先問</h3><p>資料是否足夠？<br>時點與頻率是否一致？<br>哪些數字可以重算？<br>什麼條件改變會影響結論？</p></div></aside></div></div>`;}
function caseStep(c,s,i){const l=lessonOf(c.lesson);if(i===0)return '先釐清「'+s+'」要回答的問題。'+l.body[0];if(i===1)return '把條件記錄後再使用方法。'+(l.body[1]||l.body[0]);return '將結果代回資料，檢查是否可重現。'+(l.body[2]||c.check);}
function toolsPage(tab='savings',selectedFunction='PMT'){if(!['savings','loan','cashflow','risk','chart','functions'].includes(tab))tab='savings';main.innerHTML=`<div class="container">${head('工具與公式','改變參數、觀察結果，把每個假設變成可以檢查的計算。','EXPLORE · CALCULATE · VERIFY',[['工具與公式']])}<div class="tool-tabs" aria-label="工具選擇">${[['savings','儲蓄與複利'],['loan','貸款攤還'],['cashflow','現金流評估'],['risk','風險與相關性'],['chart','圖表實驗室'],['functions','Excel 公式速查']].map(([id,s])=>`<a href="#/tools/${id}" class="tool-tab ${id===tab?'active':''}">${s}</a>`).join('')}</div><div class="page-content" id="tool-content"></div></div>`;({savings:renderSavings,loan:renderLoan,cashflow:renderCashflow,risk:renderRisk,chart:renderChart,functions:()=>renderFunctions(FUNCTIONS.some(f=>f.id===selectedFunction)?selectedFunction:'PMT')})[tab]();}
function numberField(id,label,value,min,max,step='1',note=''){return `<label class="field" for="${id}">${label}<input type="number" id="${id}" value="${value}" min="${min}" max="${max}" step="${step}" required>${note?`<small>${note}</small>`:''}</label>`;}
function result(label,value,note='',primary=false){return `<div class="result-card ${primary?'primary':''}"><small>${label}</small><strong>${value}</strong>${note?`<p>${note}</p>`:''}</div>`;}
function readNumber(id,min,max){const el=$('#'+id),n=Number(el.value);if(el.value.trim()===''||!Number.isFinite(n)||n<min||n>max)throw Error(el.previousSibling?.textContent||'請檢查輸入數值與範圍。');return n;}
function error(el,e){el.innerHTML=`<div class="error" role="alert">${E(e.message||'請檢查輸入。')}</div>`;}
function growthChart(series,names,colors){let max=Math.max(1,...series.flat()),min=Math.min(0,...series.flat()),w=700,h=235,pad=48;const X=i=>pad+i/(Math.max(1,series[0].length-1))*(w-pad-15),Y=v=>h-30-(v-min)/(max-min)*(h-50);return `<svg class="line-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${E(names.join('與'))}比較圖">${[0,.25,.5,.75,1].map(t=>`<path d="M${pad} ${Y(min+(max-min)*t)}H${w-10}" stroke="#e2e8f0"/><text x="${pad-8}" y="${Y(min+(max-min)*t)+4}" text-anchor="end" fill="#64748b" font-size="9">${fmt((min+(max-min)*t)/1000)}k</text>`).join('')}${series.map((s,k)=>`<path d="${s.map((v,i)=>(i?'L':'M')+X(i).toFixed(2)+' '+Y(v).toFixed(2)).join(' ')}" fill="none" stroke="${colors[k]}" stroke-width="2.5"/>`).join('')}${[0,.25,.5,.75,1].map(t=>`<text x="${X(t*(series[0].length-1))}" y="${h-6}" text-anchor="middle" fill="#64748b" font-size="9">${Math.round(t*(series[0].length-1))}</text>`).join('')}</svg><div class="legend-inline">${names.map((n,i)=>`<span><i style="background:${colors[i]}"></i>${n}</span>`).join('')}</div>`;}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function copy(text){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('已複製，可貼上使用')).catch(()=>fallbackCopy(text));else fallbackCopy(text);}
function fallbackCopy(text){const t=document.createElement('textarea');t.value=text;t.style.cssText='position:fixed;opacity:0';document.body.append(t);t.select();let ok=document.execCommand('copy');t.remove();toast(ok?'已複製，可貼上使用':'無法自動複製，請選取文字後複製。');}
function renderSavings(){const root=$('#tool-content');root.innerHTML=`<div class="tool-layout"><form id="savings-form" class="tool-inputs"><h2>把目標放進時間裡</h2><p>固定報酬、固定每月投入的教學模型</p><div class="inputs-fields">${numberField('sv-pv','初始本金（元）',100000,0,1000000000)}${numberField('sv-pmt','每月投入（元）',5000,0,10000000)}<div class="form-grid">${numberField('sv-rate','名目年率（%）',4,-50,50,'.1')}${numberField('sv-years','累積年數',10,1,50,'1')}</div><label class="field">投入時間<select id="sv-due"><option value="0">每月期末</option><option value="1">每月期初</option></select><small>年率除以 12，假設每月固定計息</small></label></div><div class="inline-buttons"><button type="submit" class="btn btn-primary btn-small">更新試算 →</button><button type="reset" class="btn btn-small">重設</button></div><p class="tool-note">真實投資報酬會波動。這裡用固定假設探索複利，不預測未來收益。</p></form><div id="savings-result"></div></div>`;const run=()=>{try{const pv=readNumber('sv-pv',0,1e9),pmt=readNumber('sv-pmt',0,1e7),r=readNumber('sv-rate',-50,50)/1200,years=readNumber('sv-years',1,50),n=Math.round(years*12),due=$('#sv-due').value==='1',v=FM.fv(pv,pmt,r,n,due),invest=pv+pmt*n,values=Array.from({length:n+1},(_,i)=>FM.fv(pv,pmt,r,i,due)),base=values.map((_,i)=>pv+pmt*i);$('#savings-result').innerHTML=`<div class="result-grid">${result('預計累積金額',fmt(v),'元 · 模型試算',true)}${result('總投入本金',fmt(invest),'初始本金＋定期投入')}${result('假設累積收益',fmt(v-invest),'可能為負值')}</div><div class="chart-panel"><h3>累積值與投入的路徑</h3><p>橫軸：月數 · 縱軸：金額（千元）</p>${growthChart([values,base],['假設累積值','累積投入'],['#1447e6','#d66b00'])}</div><div class="panel"><h3>對照 Excel 公式</h3><div class="code-row"><code id="sv-formula">=FV(${r.toPrecision(8)},${n},-${pmt},-${pv},${due?1:0})</code><button class="btn btn-small" id="sv-copy">複製</button></div><p class="tool-note">${due?'期初':'期末'}投入，利率與期數皆以月為單位。${Math.abs(r)<1e-12?'零利率時直接累加本金與投入。':''}</p><a class="text-link" href="#/lesson/fv">理解 FV 與期初期末的差異 ↗</a></div>`;$('#sv-copy').onclick=()=>copy($('#sv-formula').textContent);}catch(e){error($('#savings-result'),e);}};$('#savings-form').onsubmit=e=>{e.preventDefault();run();};$('#savings-form').onreset=()=>setTimeout(run,0);run();}
function renderLoan(){const root=$('#tool-content');root.innerHTML=`<div class="tool-layout"><form id="loan-form" class="tool-inputs"><h2>看懂每一期還款</h2><p>固定利率、每月期末等額還款</p><div class="inputs-fields">${numberField('ln-pv','貸款本金（元）',1000000,1,1000000000)}${numberField('ln-rate','名目年利率（%）',3,0,30,'.1')}${numberField('ln-years','貸款年數',30,1,50,'1')}</div><div class="inline-buttons"><button type="submit" class="btn btn-primary btn-small">更新試算 →</button><button type="reset" class="btn btn-small">重設</button></div><p class="tool-note">未納入手續費、保險、浮動利率或提前清償條件。逐期以未四捨五入數值計算。</p></form><div id="loan-result"></div></div>`;const run=()=>{try{const pv=readNumber('ln-pv',1,1e9),r=readNumber('ln-rate',0,30)/1200,years=readNumber('ln-years',1,50),n=Math.round(years*12),rows=FM.amortize(pv,r,n),pay=FM.payment(pv,r,n),total=rows.reduce((s,x)=>s+x.payment,0);$('#loan-result').innerHTML=`<div class="result-grid">${result('每月還款金額',fmt(pay,2),'元 · 固定利率',true)}${result('總利息',fmt(total-pv),'元')}${result('還款總金額',fmt(total),'元 · 本金與利息')}</div><div class="chart-panel"><h3>貸款餘額逐月變化</h3><p>橫軸：月數 · 縱軸：餘額（千元）</p>${growthChart([[pv,...rows.map(x=>x.balance)]],['未償本金'],['#1447e6'])}</div><div class="panel"><div class="table-top"><h3>逐期本金與利息</h3><button class="btn btn-small" id="loan-download">下載完整 CSV ↓</button></div><div class="table-wrap"><table><thead><tr><th>期數</th><th>還款額</th><th>利息</th><th>本金</th><th>期末餘額</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.period}</td><td>${fmt(x.payment,2)}</td><td>${fmt(x.interest,2)}</td><td>${fmt(x.principal,2)}</td><td>${fmt(x.balance,2)}</td></tr>`).join('')}</tbody></table></div><p class="tool-note">金額顯示至小數兩位，最後一期按剩餘本金調整。每期本金＋利息＝還款額。</p><a class="text-link" href="#/lesson/amortization">理解 IPMT 與 PPMT ↗</a></div>`;$('#loan-download').onclick=()=>download('貸款攤還表.csv','\uFEFF期數,還款額,利息,本金,期末餘額\n'+rows.map(x=>[x.period,x.payment.toFixed(2),x.interest.toFixed(2),x.principal.toFixed(2),x.balance.toFixed(2)].join(',')).join('\n'),'text/csv;charset=utf-8');}catch(e){error($('#loan-result'),e);}};$('#loan-form').onsubmit=e=>{e.preventDefault();run();};$('#loan-form').onreset=()=>setTimeout(run,0);run();}
function renderCashflow(){const root=$('#tool-content');root.innerHTML=`<div class="tool-layout"><form id="cf-form" class="tool-inputs"><h2>把現金流放在一起</h2><p>支出負數、收入正數；從同一人視角記錄</p><label class="field">現金流形式<select id="cf-mode"><option value="regular">等間隔（每年一期）</option><option value="dated">實際日期（XNPV / XIRR）</option></select></label>${numberField('cf-rate','年折現率（%）',5,-50,100,'.1')}<label class="field" for="cf-data">現金流資料<textarea id="cf-data" rows="8" spellcheck="false">-15000\n10000\n10000\n10000</textarea><small id="cf-hint">每行一筆，第一行是今日的初始投入。</small></label><div class="inline-buttons"><button type="submit" class="btn btn-primary btn-small">計算與驗證 →</button><button type="button" class="btn btn-small" id="cf-sample">載入範例</button></div><p class="tool-note">本工具對「初始負投入、其後非負收入」求唯一報酬率。複雜正負轉換仍可計算現值，但不回傳可能誤導的單一 IRR。</p></form><div id="cf-result"></div></div>`;
 function sample(){const dated=$('#cf-mode').value==='dated';$('#cf-data').value=dated?'2024-01-01, -15000\n2024-07-01, 5000\n2025-03-01, 8000\n2026-01-01, 10000':'-15000\n10000\n10000\n10000';$('#cf-hint').textContent=dated?'每行格式：YYYY-MM-DD, 金額。第一個日期為估值日；後續日期必須嚴格遞增。':'每行一筆，第一行是今日的初始投入。';run();}
 function run(){try{const r=readNumber('cf-rate',-50,100)/100,dated=$('#cf-mode').value==='dated',lines=$('#cf-data').value.trim().split(/\n/).filter(x=>x.trim());if(lines.length<2||lines.length>120)throw Error('請輸入 2–120 筆現金流。');let flows=[],dates=[],times=[];lines.forEach((line,i)=>{if(dated){const match=line.trim().match(/^(\d{4}-\d{2}-\d{2})\s*[,，]\s*(-?\d+(?:\.\d+)?)$/);if(!match)throw Error('日期資料請使用 YYYY-MM-DD, 金額，每行一筆。');const dt=Date.parse(match[1]+'T00:00:00Z');if(!Number.isFinite(dt)||new Date(dt).toISOString().slice(0,10)!==match[1])throw Error('日期不存在，請檢查年月日。');dates.push(dt);flows.push(Number(match[2]));if(i&&dt<=dates[i-1])throw Error('日期必須按先後排列，不可重複。');times.push((dt-dates[0])/86400000/365);}else{const v=Number(line.trim());if(!Number.isFinite(v))throw Error('每行請輸入一個有效金額，不要加入千分位。');flows.push(v);times.push(i);}});if(flows.some(x=>Math.abs(x)>1e12))throw Error('單筆金額請控制在一兆元以內。');const val=FM.npv(flows,r,times),rate=FM.irr(flows,times),sum=flows.reduce((s,x)=>s+x,0);if(!Number.isFinite(val))throw Error('計算超出範圍，請調整折現率或期間。');$('#cf-result').innerHTML=`<div class="result-grid">${result(dated?'XNPV 淨現值':'NPV 淨現值',fmt(val,2),'元 · 含初始現金流',true)}${result(dated?'XIRR 年化報酬':'IRR 年報酬',rate===null?'未求解':pct(rate),'單一初始投入模型')}${result('未折現現金流合計',fmt(sum),'元 · 不等於淨現值')}</div><div class="panel"><h3>每一筆現金流的現值</h3><div class="table-wrap"><table><thead><tr><th>${dated?'日期':'時點'}</th><th>現金流</th><th>折現期間（年）</th><th>現值</th></tr></thead><tbody>${flows.map((c,i)=>`<tr><td>${dated?new Date(dates[i]).toISOString().slice(0,10):i===0?'今天':'第 '+i+' 年末'}</td><td>${fmt(c,2)}</td><td>${fmt(times[i],4)}</td><td>${fmt(c/(1+r)**times[i],2)}</td></tr>`).join('')}</tbody></table></div><div class="tool-method"><b>如何驗證</b>現值總和＝${fmt(val,2)} 元。${rate===null?'此現金流不符合本工具的單一投入求解條件，或沒有可用的有限解；不以零代替。':`把 ${pct(rate,6)} 代回，淨現值約為 ${fmt(FM.npv(flows,rate,times),6)} 元。`}${dated?' 日期模式按實際天數／365 折現。':' 固定期間模式將第一行視為今天，往後各間隔一年。'}</div><p class="tool-note">Excel ${dated?'XNPV 可包含基準日現金流':'NPV 應先計算未來各期，再另外加上今日現金流'}。正 NPV 的解讀依賴折現假設，並非保證獲利。</p><a class="text-link" href="#/lesson/${dated?'xnpv':'npv'}">查看完整觀念與限制 ↗</a></div>`;}catch(e){error($('#cf-result'),e);}}
 $('#cf-form').onsubmit=e=>{e.preventDefault();run();};$('#cf-sample').onclick=sample;$('#cf-mode').onchange=sample;run();}
function renderRisk(){const root=$('#tool-content');root.innerHTML=`<div class="tool-layout"><form class="tool-inputs" id="risk-form"><h2>報酬如何一起變動？</h2><p>兩組同頻率、同日期、同長度的報酬資料</p><label class="field">資產 A 報酬（%）<textarea id="risk-a" rows="4">5, -3, 8, 2, -4, 6, 3, -2</textarea></label><label class="field">資產 B 報酬（%）<textarea id="risk-b" rows="4">2, 4, -1, 3, 5, 0, 1, 4</textarea><small>以逗號或換行分隔，輸入 5 表示 5%。每個位置必須是相同期間。</small></label>${numberField('risk-weight','資產 A 比例（%）',50,0,100,'1')}<div class="inline-buttons"><button type="submit" class="btn btn-primary btn-small">比較與驗證 →</button><button type="reset" class="btn btn-small">重設</button></div><p class="tool-note">使用母體標準差 STDEV.P，未年化。組合假設每期維持指定權重，未納入交易成本。</p></form><div id="risk-result"></div></div>`;function parse(id){const parts=$('#'+id).value.trim().split(/[,，\s]+/).filter(Boolean);if(parts.length<2||parts.length>240)throw Error('每組請輸入 2–240 筆資料。');const a=parts.map(Number);if(a.some(x=>!Number.isFinite(x)||x<=-100||x>1000))throw Error('報酬請輸入大於 −100%、不超過 1000% 的數值。');return a.map(x=>x/100);}const run=()=>{try{const a=parse('risk-a'),b=parse('risk-b'),w=readNumber('risk-weight',0,100)/100;if(a.length!==b.length)throw Error('兩組資料長度必須一致，且同一位置需對應相同日期。');const portfolio=a.map((x,i)=>w*x+(1-w)*b[i]),corr=FM.correlation(a,b),sd=x=>Math.sqrt(FM.variance(x));const cumulative=x=>{let z=100000;return[100000,...x.map(r=>z*=1+r)];};$('#risk-result').innerHTML=`<div class="result-grid">${result('資產 A 每期波動',pct(sd(a)),'母體標準差')}${result('資產 B 每期波動',pct(sd(b)),'母體標準差')}${result('配對相關係數',corr===null?'無法計算':fmt(corr,3),'樣本期間的線性關係',true)}</div><div class="chart-panel"><h3>相同初始本金的累積路徑</h3><p>初始值 100,000 元 · 橫軸：期數 · 縱軸：金額（千元）</p>${growthChart([cumulative(a),cumulative(b),cumulative(portfolio)],['資產 A','資產 B','固定權重組合'],['#1447e6','#d66b00','#1447e6'])}</div><div class="panel"><h3>平均與波動，分開閱讀</h3><div class="table-wrap"><table><thead><tr><th>項目</th><th>A</th><th>B</th><th>組合</th></tr></thead><tbody><tr><td>每期算術平均</td><td>${pct(FM.mean(a))}</td><td>${pct(FM.mean(b))}</td><td>${pct(FM.mean(portfolio))}</td></tr><tr><td>每期母體標準差</td><td>${pct(sd(a))}</td><td>${pct(sd(b))}</td><td>${pct(sd(portfolio))}</td></tr><tr><td>資料筆數</td><td>${a.length}</td><td>${b.length}</td><td>${portfolio.length}</td></tr></tbody></table></div><p class="tool-note">${corr===null?'其中一組缺少變異，相關係數未定義。':'相關係數只描述這組歷史樣本，不代表未來固定關係。'} 固定權重組合的報酬以每期權重計算，並不等於買入後不調整的持有方式。</p><a class="text-link" href="#/lesson/correlation">理解相關性與分散 ↗</a></div>`;}catch(e){error($('#risk-result'),e);}};$('#risk-form').onsubmit=e=>{e.preventDefault();run();};$('#risk-form').onreset=()=>setTimeout(run,0);run();}

const syntheticRows=FM.synthetic();
function renderChart(){const root=$('#tool-content');root.innerHTML=`<div class="chart-panel"><div class="chart-title"><h3>價格、成交量與指標</h3><span class="dataset-badge">固定合成資料 · 非真實行情</span></div><p>用同一組示範資料，觀察頻率與參數如何改變指標。</p><div class="chart-controls" style="margin-top:20px"><label class="field">時間單位<select id="chart-frequency"><option value="daily">日 K</option><option value="weekly">週 K</option></select></label><label class="field">指標組合<select id="chart-indicator"><option value="ma">均線</option><option value="macd">均線＋MACD</option><option value="kd">均線＋KD</option><option value="rsi">均線＋RSI</option><option value="bollinger">布林通道</option></select></label><label class="field">中期均線／布林期數<input id="chart-period" type="number" min="5" max="60" value="20" step="1"></label><label class="field">顯示範圍<select id="chart-range"><option value="100">最近 100 期</option><option value="180">最近 180 期</option><option value="all">全部資料</option></select></label><button class="btn btn-small" id="chart-download">下載合成資料 ↓</button></div><div id="chart-area"></div><div class="chart-readout" id="chart-readout" aria-live="polite"></div><p class="chart-hint">滑過或點選 K 線可讀取開高低收；觸控裝置也可使用下方資料表。</p><div class="legend-inline"><span><i style="background:#bb514b"></i>收盤高於或等於開盤</span><span><i style="background:#23755f"></i>收盤低於開盤</span><span id="chart-legend"></span></div><div class="tool-method" id="chart-method"></div><details class="disclosure"><summary>查看目前範圍的資料表</summary><div id="chart-data-table" class="table-wrap"></div></details></div><div class="panel"><h2>用明確規則做一次驗證</h2><p class="small muted">固定使用合成日資料：5 期 SMA 上穿 20 期 SMA，次一交易日開盤買入；下穿則次一交易日開盤賣出。初始金額 100,000 元，允許小數單位，全額投入。</p><form id="backtest-form" class="inline-buttons" style="align-items:end;margin-top:20px"><div style="max-width:180px">${numberField('bt-fee','每邊交易成本（%）',.1,0,5,'.01')}</div><button class="btn btn-primary btn-small" style="margin-bottom:17px" type="submit">執行合成資料回測 →</button></form><div id="backtest-result"></div><p class="tool-note">這個實驗不使用任何真實個股資料。結果僅用來檢查規則與成本，不能推論真實市場績效。未平倉部位按最後收盤估值；未計最終賣出費，沒有利息、稅或股息。</p></div>`;
 const draw=()=>{const period=Number($('#chart-period').value);if(!Number.isInteger(period)||period<5||period>60){$('#chart-area').innerHTML='<div class="error">期數請輸入 5–60 的整數。</div>';$('#chart-readout').textContent='';$('#chart-data-table').innerHTML='';return;}const weekly=$('#chart-frequency').value==='weekly',all=weekly?FM.weekly(syntheticRows):syntheticRows,inds=FM.indicators(all,period),len=$('#chart-range').value==='all'?all.length:Math.min(all.length,Number($('#chart-range').value)),start=all.length-len,rows=all.slice(start),kind=$('#chart-indicator').value;drawMarket(rows,inds,start,kind,period,weekly);};['chart-frequency','chart-indicator','chart-period','chart-range'].forEach(id=>$('#'+id).onchange=draw);$('#chart-download').onclick=()=>download('合成教學行情.csv','\uFEFFdate,open,high,low,close,volume\n'+syntheticRows.map(x=>[x.date,x.o,x.h,x.l,x.c,x.v].join(',')).join('\n'),'text/csv;charset=utf-8');$('#backtest-form').onsubmit=e=>{e.preventDefault();try{const fee=readNumber('bt-fee',0,5)/100,b=FM.backtest(syntheticRows,fee);$('#backtest-result').innerHTML=`<div class="result-grid">${result('策略累積報酬',pct(b.ret),'含每邊交易成本',true)}${result('最大收盤回撤',pct(b.maxdd),'逐日按收盤估值')}${result('買入持有基準',pct(b.benchmark),'同日起買入，含買入成本')}</div><p class="small muted">交易次數 ${b.trades.length} 筆 · 期末資產 ${fmt(b.end,2)} 元 · ${b.open?'仍有未平倉部位':'期末持有現金'}。基準與策略從相同可執行起始日比較。</p><details class="disclosure"><summary>查看全部交易紀錄</summary><div class="table-wrap"><table><thead><tr><th>日期</th><th>動作</th><th>開盤成交價</th><th>數量</th><th>交易成本</th></tr></thead><tbody>${b.trades.map(t=>`<tr><td>${t.date}</td><td>${t.type}</td><td>${fmt(t.price,4)}</td><td>${fmt(t.shares,4)}</td><td>${fmt(t.cost,2)}</td></tr>`).join('')}</tbody></table></div></details>`;}catch(err){error($('#backtest-result'),err);}};draw();}
function drawMarket(rows,inds,start,kind,period,weekly){const W=1040,H=kind==='ma'||kind==='bollinger'?420:570,left=55,right=55,top=25,priceBottom=290,volumeTop=315,volumeBottom=375,subTop=420,subBottom=520,step=(W-left-right)/rows.length,x=i=>left+step*(i+.5);let lo=Math.min(...rows.map(r=>r.l)),hi=Math.max(...rows.map(r=>r.h));const overlays=kind==='bollinger'?[['mid','#d66b00'],['upper','#1447e6'],['lower','#1447e6']]:[['ma5','#f59e0b'],['ma20','#0891b2'],['ma60','#7c3aed']];for(const [key]of overlays){const v=inds[key].slice(start).filter(Number.isFinite);if(v.length){lo=Math.min(lo,...v);hi=Math.max(hi,...v);}}const pad=(hi-lo)*.08;lo-=pad;hi+=pad;const y=v=>priceBottom-(v-lo)/(hi-lo)*(priceBottom-top),volmax=Math.max(...rows.map(r=>r.v));const line=(arr,Y)=>{let d='',open=false;arr.forEach((v,i)=>{if(v===null||!Number.isFinite(v)){open=false;return;}d+=(open?'L':'M')+x(i).toFixed(2)+' '+Y(v).toFixed(2)+' ';open=true;});return d;};let svg=`<svg id="market-svg" class="market-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="合成資料的 ${weekly?'週':'日'} K 線、成交量與${kind}指標">`;
 for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;svg+=`<path d="M${left} ${y(v)}H${W-right}" stroke="#e2e8f0"/><text x="${W-right+8}" y="${y(v)+4}" fill="#64748b" font-size="10">${fmt(v,1)}</text>`;}
 rows.forEach((r,i)=>{const color=r.c>=r.o?'#ba514b':'#23755f',cw=Math.max(1,Math.min(8,step*.6));svg+=`<path d="M${x(i)} ${y(r.h)}V${y(r.l)}" stroke="${color}"/><rect x="${x(i)-cw/2}" y="${Math.min(y(r.o),y(r.c))}" width="${cw}" height="${Math.max(1,Math.abs(y(r.o)-y(r.c)))}" fill="${color}"/><rect x="${x(i)-cw/2}" y="${volumeBottom-r.v/volmax*(volumeBottom-volumeTop)}" width="${cw}" height="${r.v/volmax*(volumeBottom-volumeTop)}" fill="${color}" opacity=".45"/>`;});
 overlays.forEach(([key,color])=>svg+=`<path d="${line(inds[key].slice(start),y)}" fill="none" stroke="${color}" stroke-width="1.6"/>`);svg+=`<text x="${left}" y="${volumeTop-8}" fill="#64748b" font-size="10">成交量（合成單位）</text>`;
 if(!['ma','bollinger'].includes(kind)){let arrs=[],subLo=0,subHi=100;if(kind==='macd'){arrs=[inds.dif.slice(start),inds.dea.slice(start)];subLo=Math.min(0,...arrs.flat(),...inds.hist.slice(start));subHi=Math.max(0,...arrs.flat(),...inds.hist.slice(start));}else if(kind==='kd'){arrs=[inds.kd.slice(start).map(v=>v?.k??null),inds.kd.slice(start).map(v=>v?.d??null)];}else arrs=[inds.rsi.slice(start)];const ys=v=>subBottom-(v-subLo)/(subHi-subLo||1)*(subBottom-subTop);const levels=kind==='macd'?[0]:kind==='kd'?[20,80]:[30,70];levels.forEach(v=>svg+=`<path d="M${left} ${ys(v)}H${W-right}" stroke="#e2e8f0" stroke-dasharray="4 4"/><text x="${W-right+8}" y="${ys(v)+4}" fill="#64748b" font-size="10">${fmt(v,1)}</text>`);if(kind==='macd')inds.hist.slice(start).forEach((v,i)=>{svg+=`<rect x="${x(i)-Math.max(1,step*.25)}" y="${Math.min(ys(0),ys(v))}" width="${Math.max(1,step*.5)}" height="${Math.max(1,Math.abs(ys(v)-ys(0)))}" fill="${v>=0?'#ba514b':'#23755f'}" opacity=".7"/>`;});arrs.forEach((a,i)=>svg+=`<path d="${line(a,ys)}" fill="none" stroke="${i?'#d66b00':'#1447e6'}" stroke-width="1.5"/>`);svg+=`<text x="${left}" y="${subTop-12}" fill="#64748b" font-size="10">${kind.toUpperCase()} ${kind==='macd'?'12 / 26 / 9':kind==='kd'?'9 / 3 / 3':'14'}</text>`;}
 for(let j=0;j<5;j++){const i=Math.round((rows.length-1)*j/4);svg+=`<text x="${x(i)}" y="${H-13}" fill="#64748b" font-size="10" text-anchor="middle">${rows[i].date}</text>`;}svg+=`<line id="chart-cursor" x1="0" x2="0" y1="${top}" y2="${H-35}" stroke="#64748b" stroke-dasharray="3 4" opacity="0"/><rect id="chart-hit" x="${left}" y="${top}" width="${W-left-right}" height="${H-top-35}" fill="transparent"/></svg>`;$('#chart-area').innerHTML=svg;
 const describe=i=>{const r=rows[i],k=start+i;$('#chart-readout').innerHTML=`<strong>${r.date}${weekly?'（該週最後資料日）':''}</strong><span>開 ${fmt(r.o,2)}</span><span>高 ${fmt(r.h,2)}</span><span>低 ${fmt(r.l,2)}</span><span>收 ${fmt(r.c,2)}</span><span>量 ${fmt(r.v)}</span>`;const cur=$('#chart-cursor');cur.setAttribute('x1',x(i));cur.setAttribute('x2',x(i));cur.setAttribute('opacity','.6');};const hover=ev=>{const svgEl=$('#market-svg'),rect=svgEl.getBoundingClientRect(),xx=(ev.clientX-rect.left)/rect.width*W;describe(Math.max(0,Math.min(rows.length-1,Math.floor((xx-left)/step))));};$('#chart-hit').onpointermove=hover;$('#chart-hit').onclick=hover;describe(rows.length-1);
 $('#chart-legend').innerHTML=kind==='bollinger'?'<i style="background:#1447e6"></i>上下軌 · 中軌 '+period+' 期':'<i style="background:#f59e0b"></i>5 期 <i style="background:#0891b2;margin-left:10px"></i>'+period+' 期 <i style="background:#7c3aed;margin-left:10px"></i>60 期';
 const method={ma:'SMA 使用收盤的簡單平均；期數以目前選擇的日／週資料為單位。',macd:'EMA 以第一筆收盤初始化，DIF＝EMA12−EMA26，DEA＝DIF 的 EMA9，柱體＝DIF−DEA（不乘 2）。',kd:'KD 使用 9 期高低，RSV 平滑係數 1/3，K、D 起始 50；高低相同時 RSV 設為 50。',rsi:'RSI 使用 14 期 Wilder 平滑；前 14 次變動建立初始平均；完全不變時設為 50。',bollinger:`中軌＝${period} 期 SMA，上下軌＝中軌 ± 2 倍母體標準差。`};$('#chart-method').innerHTML=`<b>計算慣例與資料範圍</b>${method[kind]} ${weekly?'週 K 依週一分組，開盤取首筆、收盤取末筆、最高最低取極值、量加總；日期標記該週最後資料日。':'資料只建立週一至週五，未模擬真實交易所休市。'} 指標先在完整資料計算，再切出顯示範圍；無足夠期數時不畫線。<br>完整資料 ${FM.synthetic().length} 筆合成日行情；目前顯示 ${rows.length} 期，${rows[0].date} 至 ${rows.at(-1).date}。`;
 $('#chart-data-table').innerHTML=`<table><thead><tr><th>資料日</th><th>開盤</th><th>最高</th><th>最低</th><th>收盤</th><th>成交量</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.date}</td><td>${fmt(r.o,2)}</td><td>${fmt(r.h,2)}</td><td>${fmt(r.l,2)}</td><td>${fmt(r.c,2)}</td><td>${fmt(r.v)}</td></tr>`).join('')}</tbody></table>`;
}
function renderFunctions(selected='PMT'){const root=$('#tool-content');root.innerHTML=`<label class="sr-only" for="function-search">搜尋函數</label><input class="search-inline" id="function-search" placeholder="搜尋函數名稱或用途，例如 NPV、利息…"><div class="function-layout"><div id="function-list" class="function-list"></div><div class="panel function-detail" id="function-detail"></div></div>`;let current=selected;const show=id=>{current=id;const f=FUNCTIONS.find(x=>x.id===id);$('#function-detail').innerHTML=`<div class="eyebrow">FORMULA REFERENCE</div><h2 style="margin-top:15px">${f.id}<span>${f.title}</span></h2><p class="muted">${f.desc}</p><h3>語法與參數</h3><code class="code">${E(f.syntax)}</code><p class="small">${E(f.notes)}</p><h3>可複製的示範公式</h3><div class="code-row"><code>${E(f.example)}</code><button class="btn btn-small" id="function-copy">複製</button></div><p class="tool-note">公式使用示範條件或儲存格位置，貼上前請對照你的資料與 Excel 環境。</p><a class="btn btn-primary btn-small" style="margin-top:20px" href="#/lesson/${f.lesson}">閱讀完整知識點 →</a><div class="disclosure"><a class="text-link" href="https://support.microsoft.com/excel" target="_blank" rel="noopener noreferrer">Microsoft Excel 官方支援 ↗</a></div>`;$('#function-copy').onclick=()=>copy(f.example);list();};function list(){const q=$('#function-search').value.toLowerCase(),items=FUNCTIONS.filter(f=>[f.id,f.title,f.desc].join(' ').toLowerCase().includes(q));$('#function-list').innerHTML=items.length?items.map(f=>`<button class="${current===f.id?'selected':''}" data-function="${f.id}"><strong>${f.id}</strong><span>${f.title}</span></button>`).join(''):'<p class="small muted">找不到符合的函數。</p>';document.querySelectorAll('[data-function]').forEach(b=>b.onclick=()=>show(b.dataset.function));}$('#function-search').oninput=list;show(current);}
function promptsPage(){main.innerHTML=`<div class="container">${head('AI 提問：讓思考有依據','把問題、資料、方法與驗證要求說清楚，讓 AI 成為可以檢查的協作夥伴。','ASK BETTER · VERIFY BETTER',[['AI 提問']])}<div class="prompt-grid page-content">${PROMPTS.map(p=>`<a class="prompt-card" href="#/prompt/${p.id}"><span class="tag">${p.category}</span><h3>${p.title}</h3><p>${p.desc}</p><div class="card-bottom"><span>填寫條件 · 複製使用</span><span class="card-arrow">↗</span></div></a>`).join('')}</div></div>`;}
function promptPage(id){const p=PROMPTS.find(x=>x.id===id);if(!p)return notFound();main.innerHTML=`<div class="container">${head(p.title,p.desc,'STRUCTURED PROMPT',[['AI 提問','#/prompts'],[p.category]])}<div class="prompt-layout page-content"><form class="panel" id="prompt-form"><h3>填入你的條件</h3>${p.fields.map(([id,label,value])=>`<label class="field">${label}<textarea id="prompt-${id}" rows="${value.length>35?3:2}" maxlength="2000">${E(value)}</textarea></label>`).join('')}<button type="reset" class="btn btn-small">回到示範條件</button><p class="tool-note">填入的內容只在目前頁面產生文字，不會傳送給 AI 服務。複製後可在你使用的 AI 工具貼上。</p></form><div class="panel"><div class="table-top"><h3>你的提問模板</h3><span class="tag">可編輯條件</span></div><div class="prompt-output" id="prompt-output"></div><button class="btn btn-primary" id="prompt-copy">複製完整提問 →</button><div class="tool-method"><b>收到回答後，繼續追問</b>哪些是已知事實？哪些是你補入的假設？可以提供原始數據與重算方式嗎？如果條件改變，結論還成立嗎？</div></div></div></div>`;const update=()=>{let t=p.template;p.fields.forEach(([id])=>t=t.replaceAll('{'+id+'}',$('#prompt-'+id).value||'（待補充）'));$('#prompt-output').textContent=t;};$('#prompt-form').oninput=update;$('#prompt-form').onreset=()=>setTimeout(update,0);$('#prompt-form').onsubmit=e=>e.preventDefault();$('#prompt-copy').onclick=()=>copy($('#prompt-output').textContent);update();}
function myPage(tab='saved'){const finished=state.done.map(lessonOf).filter(Boolean),saved=state.saved.map(lessonOf).filter(Boolean),notes=Object.entries(state.notes).filter(([id,t])=>lessonOf(id)&&t.trim());main.innerHTML=`<div class="container">${head('我的學習','回到上次的探索，整理收藏與筆記，看見自己逐步累積的理解。','YOUR PERSONAL WORKSPACE',[['我的學習']])}<div class="page-content"><div class="progress-overview"><div class="panel"><h3>知識點學習進度</h3><div class="large-progress">${Math.round(state.done.length/LESSONS.length*100)}<span>%</span></div><div class="progress-bar"><i style="width:${state.done.length/LESSONS.length*100}%"></i></div><p class="small muted">${state.done.length} / ${LESSONS.length} 個知識點已標記完成</p></div><div class="panel"><h3>接續你的探索</h3>${state.last?`<div class="list-row"><div><small>上次閱讀</small><h3>${lessonOf(state.last).title}</h3></div><a class="btn btn-primary btn-small" href="#/lesson/${state.last}">繼續 →</a></div>`:`<p class="muted small">選一條路徑，開始累積第一個知識點。</p><a class="btn btn-primary btn-small" href="#/learn" style="margin-top:18px">探索課程 →</a>`}<p class="tool-note">${storageOK?'進度、收藏與筆記僅保存在目前瀏覽器。清除瀏覽器資料會移除紀錄；可匯出備份。':'目前無法存取瀏覽器儲存，紀錄只在這次開啟期間保留，請匯出備份。'}</p></div></div><div class="toolbar my-tabs">${[['saved','收藏知識點',saved.length],['done','已完成',finished.length],['notes','我的筆記',notes.length]].map(([id,s,n])=>`<button class="filter ${tab===id?'active':''}" data-my-tab="${id}">${s} ${n}</button>`).join('')}<button class="btn btn-small" style="margin-left:auto" id="export-progress">匯出學習紀錄 ↓</button><label class="btn btn-small" for="import-progress" style="cursor:pointer">匯入備份 ↑</label><input type="file" accept=".json,application/json" id="import-progress" hidden></div>${tab==='notes'?(notes.length?`<div class="stack">${notes.map(([id,t])=>`<div class="panel"><a class="text-link" href="#/lesson/${id}">${lessonOf(id).title} ↗</a><p style="white-space:pre-wrap;margin-top:15px;font-size:14px">${E(t)}</p></div>`).join('')}</div>`:empty('還沒有筆記。閱讀時用自己的話留下觀念與問題。')):((tab==='done'?finished:saved).length?`<div class="lesson-grid">${(tab==='done'?finished:saved).map(lessonCard).join('')}</div>`:empty(tab==='done'?'完成閱讀後，可以在知識點頁面標記完成。':'把想重讀的知識點加入收藏，下次從這裡回來。'))}<div class="section-head" style="margin-top:45px"><h2 style="font-size:23px">學習路徑進度</h2></div><div class="path-grid">${PATHS.map(pathCard).join('')}</div></div></div>`;document.querySelectorAll('[data-my-tab]').forEach(b=>b.onclick=()=>myPage(b.dataset.myTab));$('#export-progress').onclick=()=>download('投資理財學習紀錄.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2),'application/json');$('#import-progress').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('備份檔案過大。');const raw=JSON.parse(await file.text());if(raw.version!==1||!Array.isArray(raw.done)||!Array.isArray(raw.saved)||!raw.notes||typeof raw.notes!=='object')throw Error('這不是可辨識的學習備份。');state.done=[...new Set([...state.done,...raw.done.filter(id=>lessonOf(id))])];state.saved=[...new Set([...state.saved,...raw.saved.filter(id=>lessonOf(id))])];for(const[id,t]of Object.entries(raw.notes)){if(lessonOf(id)&&typeof t==='string'&&t.length<=50000)state.notes[id]=t;}for(const[id,v]of Object.entries(raw.answers||{})){if(lessonOf(id)&&Number.isInteger(v)&&v>=0&&v<lessonOf(id).choices.length)state.answers[id]=v;}save();myPage(tab);toast('已合併匯入的進度與收藏；同一知識點的筆記以備份內容更新。');}catch(err){toast(err.message||'無法讀取備份。');}};}
function empty(text){return `<div class="empty">${E(text)}<br><a class="btn btn-small" href="#/learn">探索知識點 →</a></div>`;}
function glossaryPage(){main.innerHTML=`<div class="container">${head('知識名詞表','用白話定義開始理解，再連到原理、範例、誤解與實作。','WORDS INTO UNDERSTANDING',[['知識名詞表']])}<label class="sr-only" for="glossary-search">搜尋名詞</label><input id="glossary-search" class="search-inline" placeholder="搜尋中文名稱、英文縮寫或用途…"><div id="glossary-list" class="glossary-grid page-content"></div></div>`;const update=()=>{const q=$('#glossary-search').value.toLowerCase(),items=LESSONS.filter(l=>[l.title,l.en,l.summary,...l.body].join(' ').toLowerCase().includes(q));$('#glossary-list').innerHTML=items.length?items.map(l=>`<a class="glossary-card" href="#/lesson/${l.id}"><small>${E(l.en)}</small><h3>${l.title}</h3><p>${E(l.body[0])}</p><span class="text-link">理解原理、範例與限制 ↗</span></a>`).join(''):empty('找不到這個名詞，試試英文縮寫或相關用途。');};$('#glossary-search').oninput=update;update();}
function aboutPage(){main.innerHTML=`<div class="container reading-width">${head('教材與資料說明','理解這個學習空間的內容、資料與使用方式。','ABOUT THIS LEARNING SPACE',[['教材與資料說明']])}<div class="page-content"><article class="article"><h2>探究方法，練習判斷</h2><p>這裡以理財觀念、Excel 財務模型與 AI 分析為主軸，將知識點、案例和工具互相連結。每個主題都有定義、方法、範例、限制與理解練習，可依路徑學習，也可搜尋自己的問題。</p><h2>內容與案例</h2><p>內容依使用者提供的投資理財教材重新編排，並在分類、資料頻率與驗證方法上補充說明。案例頁提供問題背景、研究步驟與檢核重點；歷史股市案例不代表當前建議。</p><h2>資料與附件的狀態</h2><p>目前沒有教材提及的原始試算表、股價 CSV 與程式附件。個股案例因此提供方法導讀，不宣稱重現精確買賣點。圖表實驗室使用固定、可下載的合成 OHLCV 資料，資料日期只用於教學示範。</p><p>現有網站是知識點重編與互動教學版，尚未逐段收錄掃描教材的全部文字、圖表與完整 AI 對話。後續全文整理仍需要逐項校對與附件補齊。</p><h2>計算工具的範圍</h2><p>儲蓄與貸款工具使用固定條件；現金流工具明示時點與求解限制；風險工具不自動年化。圖表參數與指標慣例在各工具內提供。模型沒有涵蓋的費用、契約或不確定性，應由使用者另行納入。</p><h2>學習紀錄</h2><p>完成狀態、收藏、測驗與筆記儲存在目前瀏覽器。網站沒有帳號同步，也不會將提問模板內容自動傳送給 AI 服務。可在「我的學習」匯出、匯入備份。</p><h2>延伸查證</h2><p class="small muted">以下提供公式與觀念的官方參考，閱讀操作教學時也請確認自己的工具版本與產品條件。</p>${SOURCES.map(([t,url,n])=>`<a class="source-link" href="${url}" target="_blank" rel="noopener noreferrer">${t} ↗<small>${n}</small></a>`).join('')}<div class="callout"><b>關於學習架構</b>「學習路徑」是依目標推薦的順序；「主題模組」集合相關知識；「知識點」解釋一個概念或方法；「案例實作」連回具體問題；「工具與公式」協助計算與查詢；「AI 提問」讓任務與驗證要求更明確。</div></article></div></div>`;}
function notFound(){main.innerHTML=`<div class="container">${head('這個主題還找不到','可以從課程地圖或搜尋繼續探索。','KEEP EXPLORING')}<div class="page-content"><a class="btn btn-primary" href="#/learn">回到課程地圖 →</a></div></div>`;}
function route(){const raw=location.hash.slice(1)||'/',parts=raw.split('/').filter(Boolean);$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.hash.split('/')[1]===parts[0]||(parts[0]==='lesson'&&a.hash==='#/learn')||(parts[0]==='case'&&a.hash==='#/cases')||(parts[0]==='prompt'&&a.hash==='#/prompts')));document.title='投資理財的探究與實作';const routes={learn:()=>learn(parts[1]),path:()=>pathPage(parts[1]),lesson:()=>lessonPage(parts[1]),cases:()=>casesPage(),case:()=>casePage(parts[1]),tools:()=>toolsPage(parts[1],parts[2]),prompts:promptsPage,prompt:()=>promptPage(parts[1]),my:()=>myPage(),glossary:glossaryPage,about:aboutPage};(parts.length?routes[parts[0]]||notFound:home)();window.scrollTo(0,0);}
const dialog=$('#search-dialog');let searchFrom=null;function closeSearch(){dialog.close();searchFrom?.focus();}$('#search-open').onclick=()=>{searchFrom=document.activeElement;dialog.showModal();$('#global-search').focus();search();};$('#search-close').onclick=closeSearch;dialog.onclick=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSearch();}};
function search(){const q=$('#global-search').value.trim().toLowerCase(),items=[...LESSONS.map(l=>({type:'知識點',title:l.title,desc:l.summary,text:[l.en,...l.body,l.example,l.caution].join(' '),url:'#/lesson/'+l.id})),...FUNCTIONS.map(f=>({type:'Excel 函數',title:f.id+' · '+f.title,desc:f.desc,text:f.syntax+' '+f.notes,url:'#/tools/functions/'+f.id})),...CASES.map(c=>({type:'案例實作',title:c.title,desc:c.desc,text:[c.context,...c.steps,c.check].join(' '),url:'#/case/'+c.id})),...PROMPTS.map(p=>({type:'AI 提問',title:p.title,desc:p.desc,text:p.template,url:'#/prompt/'+p.id}))];const aliases={'房貸':'貸款','標準差':'波動','投資組合':'資產配置'};let list=q?items.filter(i=>[i.title,i.desc,i.text].join(' ').toLowerCase().includes(q)||aliases[q]&&[i.title,i.desc,i.text].join(' ').includes(aliases[q])):items.filter(i=>['SMART','PMT','現值 PV','MACD','資產配置'].some(t=>i.title.includes(t))).slice(0,6);$('#search-results').innerHTML=`<p class="search-caption" style="margin-top:18px">${q?'找到 '+list.length+' 項結果'+(list.length>40?'，先顯示 40 項':''):'從熱門知識開始'}</p>`+(list.length?list.slice(0,40).map(i=>`<a class="search-result" href="${i.url}"><small>${i.type}</small><h3>${E(i.title)}</h3><p>${E(i.desc)}</p></a>`).join(''):'<p class="small muted">沒有符合結果，試試名詞縮寫、同義詞或用途。</p>');$('#search-results').querySelectorAll('a').forEach(a=>a.onclick=()=>{dialog.close();if(location.hash===a.hash)route();});}$('#global-search').oninput=search;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#search-open').click();}});$('#menu').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));};document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView();};window.addEventListener('hashchange',route);route();
})();
